INSERT INTO articles (id, title, slug, excerpt, content, image, category_id, author_id, featured, created_at, updated_at, status, meta_title, meta_description, source_name, source_url) VALUES
('8', 'Персонализираната mRNA вакцина го преполови ризикот од враќање на меланом по пет години', 'personaliziranata-mrna-vakcina-go-prepolovi-rizikot-od-vrakjanje-na-melanom-po-pet-godini', 'Клиничко испитување покажа дека персонализираната mRNA вакцина на Moderna, во комбинација со имунотерапија, го намалува ризикот од враќање на меланом за 50% по пет години.', '<p>На престижната конференција на ASCO 2026 (Американско здружение за клиничка онкологија) беа презентирани долгоочекуваните петгодишни резултати од клиничкото испитување на персонализираната mRNA вакцина против меланом, развиена од Moderna во соработка со Merck. Резултатите, објавени и истовремено во престижното списание New England Journal of Medicine, покажуваат дека вакцината, кога се користи во комбинација со имунотерапевтскиот лек pembrolizumab (Keytruda), го намалува ризикот од релапс на меланомот за 50% кај пациентите по период од пет години, во споредба со пациентите кои примале само имунотерапија.</p><p></p><p>Станува збор за персонализирана вакцина - секој пациент добива вакцина дизајнирана специфично за неговиот тумор. Процесот започнува со секвенционирање на ДНК од туморот на пациентот, по што алгоритми за вештачка интелигенција идентификуваат до 34 неоантигени - мутации кои се единствени за тој конкретен тумор. Врз основа на овие податоци, mRNA вакцината е програмирана да го научи имунолошкиот систем на пациентот да ги препознае и нападне токму тие специфични мутации.</p><p>Клиничкото испитување, познато како KEYNOTE-942, вклучи 157 пациенти со високоризичен меланом кои претходно биле подложени на хируршка ресекција на туморот. Пациентите беа поделени во две групи: едната група примаше комбинација на mRNA вакцина и pembrolizumab, додека контролната група примаше само pembrolizumab. По медијан период на следење од 5,2 години, резултатите покажаа дека 74,8% од пациентите во групата со вакцина останале без релапс на болеста, во споредба со 55,6% во контролната група.</p><p>Д-р Џефри С. Вебер, главен истражувач на студијата од NYU Langone Health, изјави: „Овие резултати претставуваат значаен чекор напред во третманот на меланом. За прв пат гледаме дека персонализираната mRNA вакцина, кога се додава на стандардната имунотерапија, обезбедува толку значајно и трајно подобрување на преживувањето без болест. Со оглед на тоа дека станува збор за вакцина која се прилагодува на туморите на секој поединечен пациент, ова отвора сосема нова ера во персонализираната онкологија.“</p><p>Профилот на безбедност на вакцината беше поволен. Најчестите несакани ефекти вклучуваа замор (48%), реакција на местото на инјектирање (39%) и треска (24%). Сериозни несакани ефекти поврзани со третманот беа забележани кај 12% од пациентите во групата со вакцина, во споредба со 8% во контролната група, но повеќето беа управливи и реверзибилни.</p><p>Она што е особено значајно е дека придобивката од вакцината беше конзистентна во сите подгрупи на пациенти, вклучително и кај оние со BRAF мутации, кај постари пациенти и кај пациенти со различна големина на примарниот тумор. Имунолошката анализа покажа дека вакцината индуцира робустен Т-клеточен одговор кај 89% од вакцинираните пациенти, што силно корелира со подобриот клинички исход.</p><p>Иако овие резултати се ветувачки, експертите предупредуваат дека потребни се дополнителни испитувања во поголем обем пред вакцината да стане стандардна опција за сите пациенти со меланом. Во моментов се во тек неколку фаза 3 клинички испитувања кои вклучуваат илјадници пациенти, не само со меланом, туку и со други видови на рак, вклучително рак на бели дробови, рак на панкреас и колоректален карцином.</p><p>За македонскиот здравствен систем, оваа вест е од големо значење бидејќи отвора можност за учество во меѓународни клинички испитувања и пристап до најсовремените терапии. Онколозите во земјава треба да бидат подготвени за овие иновации, а здравствените власти да размислат за регулаторни рамки кои ќе овозможат брз пристап до ваквите терапии откако ќе добијат одобрение од регулаторните агенции.</p><p>Следниот чекор ќе биде аплицирање за одобрение од FDA и EMA, што се очекува во текот на 2027 година. Доколку биде одобрена, персонализираната mRNA вакцина би можела да стане достапна за пациентите ширум светот, вклучително и во Северна Македонија, преку механизмите на СЗО и глобалните здравствени партнерства.</p>', '/uploads/img101.jpg', '5', '1', 'true', '2026-06-03T15:54:28.077Z', '2026-06-03T16:10:43.797Z', 'DRAFT', 'mRNA вакцина против меланом - нови резултати', 'Клиничко испитување покажа дека персонализираната mRNA вакцина на Moderna го намалува ризикот од враќање на меланом за 50% по пет години.', 'ASCO 2026 / NYU Langone Health / NBC News', 'https://www.nbcnews.com/health/health-news/moderna-melanoma-vaccine-results-asco-2026'),
('9', 'Револуционерна терапија со матични клетки го поправа оштетеното срце - ново клиничко испитување во NEJM', 'revolucionerna-terapija-so-matichni-kletki-go-poprava-oshtetenoto-srce-novo-klinichko-ispituvanje-vo-nejm', 'Студија во New England Journal of Medicine покажува дека биолошко ткиво од матични клетки, всадено на срцето, ја подобрува неговата функција кај пациенти со срцева слабост.', '<p>Најновото издание на престижното медицинско списание New England Journal of Medicine (NEJM) донесе револуционерна студија која може да го промени начинот на лекување на срцевата слабост. Истражувачите од Медицинскиот факултет Харвард и Бригам и Женската болница во Бостон развија иновативна терапија базирана на матични клетки, која создава биолошко ткиво способно да се вгради на оштетениот срцев мускул и значително да ја подобри неговата функција.</p><p></p><p>Срцевата слабост претставува еден од водечките глобални здравствени проблеми, погодувајќи околу 64 милиони луѓе ширум светот. Според Светската здравствена организација, оваа состојба е одговорна за значителен број хоспитализации и смртни случаи, а досегашните терапии главно се насочени кон контрола на симптомите без можност за регенерација на оштетеното срцево ткиво.</p><p>Новата терапија, наречена CardiPatch, користи индуцирани плурипотентни матични клетки (iPSC) кои се диференцираат во кардиомиоцити - срцеви мускулни клетки. Овие клетки потоа се нанесуваат на биоразградлив скеле-материјал, создавајќи тридимензионален ткивен графт кој морфолошки и функционално наликува на природниот срцев мускул.</p><p>Клиничкото испитување, спроведено во фаза 2, вклучи 45 пациенти со напредната срцева слабост (класа III според NYHA класификацијата), кои биле подложени на процедурата на отворено срце за вградување на биолошкиот графт. Резултатите, објавени по 18 месеци следење, покажаа дека 82% од пациентите доживеале значително подобрување на фракцијата на исфрлање на левата комора (LVEF), со просечно зголемување од 12 процентни поени. Дополнително, 67% од пациентите покажале подобрување во функционалната способност, мерено преку шестминутниот тест за одење.</p><p>Водечкиот автор на студијата, д-р Ричард Т. Ли од Харвард, изјави: „Овој пристап претставува парадигматска промена во третманот на срцевата слабост. Наместо само да ги ублажуваме симптомите со лекови, ние сега создаваме вистински жив ткивен графт кој се интегрира со постоечкиот срцев мускул и активно придонесува за неговата контрактилна функција. Ова е чекор кон вистинска регенеративна кардиологија.“</p><p>Една од најзначајните предности на оваа терапија е тоа што матичните клетки се добиваат од самиот пациент (аутологен графт), со што се избегнува потребата од имуносупресивна терапија и се намалува ризикот од одбивање на графтот. Процесот на создавање на персонализираниот графт трае приближно четири недели, што е временска рамка компатибилна со планирањето на кардиохируршката интервенција.</p><p>Профилот на безбедност беше охрабрувачки. Најчестите несакани настани вклучуваа аритмии (24%), кои беа успешно контролирани со стандардна антиаритмична терапија. Сериозни несакани ефекти беа забележани кај 8% од пациентите, но ниту еден не беше директно поврзан со самиот графт.</p><p>За македонските кардиолози и пациенти, оваа вест отвора надеж дека во иднина може да стане достапна и во нашата земја. Иако технологијата е во рана фаза на клинички испитувања и се очекува да поминат уште неколку години пред таа да биде широко достапна, македонскиот центар за срцеви заболувања би можел да се вклучи во идните фаза 3 мултицентрични студии.</p><p>Истражувачите планираат да започнат фаза 3 клиничко испитување до крајот на 2027 година, во кое ќе бидат вклучени повеќе од 500 пациенти од 30 медицински центри ширум светот. Доколку резултатите бидат потврдени, биолошкиот графт би можел да добие одобрение од регулаторните агенции во рок од 5 до 7 години, означувајќи нова ера во лекувањето на срцевата слабост.</p>', '/uploads/img103.jpg', '2', '1', 'true', '2026-06-03T15:57:53.357Z', '2026-06-03T16:10:43.812Z', 'DRAFT', 'Матични клетки за срце - нов лек во NEJM', 'Студија во New England Journal of Medicine покажува дека биолошко ткиво од матични клетки, всадено на срцето, ја подобрува неговата функција кај пациенти со срцева слабост.', 'New England Journal of Medicine', 'https://www.nejm.org/'),
('10', 'Ебола се шири во Централна Африка - СЗО алармира поради 500+ случаи и без одобрена вакцина', 'ebola-se-shiri-vo-centralna-afrika-szo-alarmira-poradi-500-sluchai-i-bez-odobrena-vakcina', 'Светската здравствена организација известува за повеќе од 513 случаи и над 130 смртни случаи од ебола во ДР Конго и Уганда, предизвикани од сојот Bundibugyo за кој нема одобрена вакцина.', '<p>Светската здравствена организација (СЗО) објави алармантен извештај за епидемијата на ебола која се шири во Централна Африка, со повеќе од 513 потврдени случаи и 132 смртни случаи во Демократска Република Конго и Уганда. Она што особено ја загрижува меѓународната здравствена заедница е фактот дека актуелната епидемија е предизвикана од сојот Bundibugyo (BDBV), за кој за разлика од попознатиот сој Заир (EBOV), сè уште нема одобрена вакцина ниту специфична антивирусна терапија.</p><p></p><p>Првите случаи беа пријавени во средината на мај 2026 година во североисточниот дел на ДР Конго, во провинцијата Северно Киву, регион кој веќе има историја на епидемии на ебола. Брзо потоа, вирусот се прошири преку границата во соседна Уганда, каде досега се потврдени 87 случаи во областите Касeсе и Бундибугјо. СЗО проценува дека репродуктивниот број (R0) на актуелната епидемија изнесува 2,1, што значи дека секој заразен просечно го пренесува вирусот на повеќе од две лица, индикација за брзо ширење доколку не се преземат итни контролни мерки.</p><p>Bundibugyo е еден од четирите познати соеви на ебола вирус, покрај Заир (EBOV), Судан (SUDV) и Тај Форест (TAFV). Иако смртноста кај Bundibugyo (околу 30-40%) е пониска од онаа на Заир сојот (50-90%), неговата способност за брзо ширење и недостатокот на вакцина го прават особено опасен. Постоечките вакцини против ебола, како rVSV-ZEBOV (Merck) и Ad26.ZEBOV (Johnson & Johnson), се развиени исклучиво за Заир сојот и не обезбедуваат вкрстена заштита против Bundibugyo.</p><p>Д-р Мајкл Рајан, извршен директор на Програмата за итни здравствени ситуации на СЗО, изјави на итната прес-конференција: „Се соочуваме со значителен предизвик бидејќи нашите главни алатки за контрола на ебола - вакцините - не се ефикасни против овој сој. Мораме да се потпреме на класичните мерки на јавното здравство: изолација на случаи, следење на контакти, безбедни погреби и зајакнување на инфективната контрола во здравствените установи. Истовремено, работиме со забрзано темпо на развој на вакцина специфична за BDBV, но таа веројатно нема да биде достапна пред средината на 2027 година.“</p><p>Центрите за контрола и превенција на болести (CDC) во Атланта испратија тим од 30 епидемиолози и специјалисти за инфективна контрола во погодените региони, додека Европската агенција за лекови (EMA) објави забрзана процедура за развој на вакцини и терапии насочени кон Bundibugyo сојот. Неколку фармацевтски компании, вклучително и Janssen и Cepheid, веќе започнаа предклинички испитувања за кандидат-вакцини базирани на mRNA технологијата која се покажа успешна против COVID-19.</p><p>Симптомите на Bundibugyo инфекцијата вклучуваат ненадејна треска, силна главоболка, болки во мускулите и зглобовите, повраќање, дијареја и, во напредната фаза, хеморагични манифестации. Инкубациониот период се движи од 2 до 21 ден, а дијагнозата се потврдува преку RT-PCR тестирање. СЗО апелира до сите земји да зајакнат надзор на границите и да подготват планови за одговор.</p><p>За Северна Македонија, ризикот од директен пренос моментално е многу низок, но македонските здравствени власти се во состојба на подготвеност. Министерството за здравство издаде препорака за патниците кои патуваат во Централна Африка да избегнуваат контакт со потенцијално заразени лица и да се придржуваат до строги хигиенски мерки. Институтот за јавно здравје на Република Северна Македонија воспостави комуникација со СЗО и ЕЦДЦ за редовна размена на информации.</p><p>Оваа епидемија доаѓа во време кога глобалниот здравствен систем е сè уште оптоварен со последиците од COVID-19 пандемијата, што дополнително ја отежнува координацијата на меѓународниот одговор. СЗО апелира до меѓународната заедница за итна финансиска поддршка од 150 милиони долари за справување со епидемијата, но до моментот на пишување на овој извештај, собрани се помалку од 30% од потребната сума.</p><p>Експертите предупредуваат дека доколку не се преземат итни мерки, бројот на случаи би можел да надмине неколку илјади во наредните недели, со потенцијал за проширување во соседните држави, вклучително Руанда, Бурунди и Јужен Судан. СЗО ја класифицира актуелната епидемија како регионална закана од висок ризик и размислува за свикување на Комитетот за итни случаи според Меѓународните здравствени регулативи.</p>', '/uploads/img121.jpg', '11', '1', 'true', '2026-06-03T15:58:18.139Z', '2026-06-03T16:10:43.818Z', 'DRAFT', 'Епидемија на ебола 2026 - СЗО предупредува', 'Светската здравствена организација известува за повеќе од 513 случаи и над 130 смртни случаи од ебола во ДР Конго и Уганда, предизвикани од сојот Bundibugyo за кој нема одобрена вакцина.', 'World Health Organization / CDC', 'https://www.who.int/emergencies/disease-outbreak-news'),
('11', 'Нови насоки за превентивни прегледи - препораки за 2026 година', 'novi-nasoki-za-preventivni-pregledi-preporaki-za-2026-godina', 'Министерството за здравство објави ажурирани препораки за редовни превентивни прегледи, прилагодени според возраста и ризик-факторите.', '<p>Министерството за здравство на Република Северна Македонија, во соработка со Светската здравствена организација, објави ажурирани насоки за превентивни здравствени прегледи за 2026 година. Новите препораки се базираат на најновите европски и светски стандарди за превентивна медицина и земаат предвид специфичните здравствени потреби на населението во земјава.</p><p></p><p>Според новите насоки, се препорачува секој граѓанин над 18-годишна возраст да направи основен превентивен преглед најмалку еднаш годишно. Овој преглед вклучува мерење на крвен притисок, анализа на крв и урина, ЕКГ и општ преглед од матичен лекар. За лицата над 40 години, препораките вклучуваат дополнителни скрининг тестови, вклучително мамографија за жени и ПСА тест за мажи.</p><p>Посебен акцент е ставен на превенцијата на кардиоваскуларните заболувања, кои се водечка причина за смрт во Северна Македонија. Новите насоки препорачуваат редовно мерење на липиден профил (холестерол и триглицериди) почнувајќи од 25-годишна возраст, како и скрининг за дијабетес тип 2 кај лица со зголемен ризик.</p><p>Значајна новина во препораките за 2026 година е вклучувањето на скрининг за ментално здравје како составен дел на превентивните прегледи. Ова доаѓа како резултат на зголемената свесност за важноста на менталното здравје и зголемениот број на случаи на анксиозност и депресија во пост-пандемискиот период.</p><p>Препораките исто така вклучуваат и имунизациски календар за возрасни, со посебен акцент на вакцинација против грип, пневмокок и ХПВ. Здравствените власти апелираат до граѓаните да ги искористат бесплатните превентивни прегледи кои се обезбедени преку Фондот за здравство.</p>', '/uploads/img109.jpg', '1', '1', 'true', '2026-06-03T16:16:14.252Z', '2026-06-03T16:25:27.650Z', 'DRAFT', 'Превентивни прегледи 2026 - нови препораки', 'Ажурирани препораки за превентивни здравствени прегледи во Северна Македонија за 2026 година.', 'Министерство за здравство на РСМ', 'https://zdravstvo.gov.mk/'),
('12', 'Телемедицината го револуционизира пристапот до здравствена заштита', 'telemedicinata-go-revolucionizira-pristapot-do-zdravstvena-zashtita', 'Дигиталните здравствени услуги овозможуваат брза и ефикасна консултација со лекар од далечина.', '<p>Телемедицината, како еден од најбрзо растечките сегменти на современото здравство, го трансформира начинот на кој пациентите пристапуваат до медицинска нега. Благодарение на напредокот на дигиталните технологии и зголемената достапност на интернет, се повеќе здравствени установи во Северна Македонија воведуваат можност за онлајн консултации.</p><p></p><p>Според последните податоци од Институтот за јавно здравје, бројот на телемедицински консултации во земјава се зголемил за 340% во периодот 2023-2025 година. Најголем интерес покажуваат пациентите од руралните средини, каде пристапот до специјалистичка здравствена заштита е ограничен.</p><p>Телемедицината нуди бројни предности: намалување на времето за чекање, избегнување на непотребни патувања, помала изложеност на инфекции во болнички средини и олеснет пристап за лицата со попреченост и хронични заболувања. Особено значајна е улогата на телемедицината во следењето на хронични пациенти, како оние со дијабетес, хипертензија и астма.</p><p>Министерството за здравство најави дека до крајот на 2026 година ќе биде лансирана национална платформа за телемедицина, која ќе овозможи интегриран пристап до сите здравствени установи во земјава. Платформата ќе вклучува можност за закажување прегледи, онлајн консултации и дигитално управување со медицинска документација.</p>', '/uploads/img110.jpg', '1', '1', 'false', '2026-06-03T16:16:14.285Z', '2026-06-03T16:25:27.646Z', 'DRAFT', 'Телемедицина - дигитална револуција во здравството', 'Како телемедицината го трансформира пристапот до здравствена заштита во Северна Македонија.', 'СЗО - Дигитално здравство', 'https://www.who.int/health-topics/digital-health'),
('13', 'Нова студија открива дека умереното вежбање го намалува ризикот од срцев удар за 35%', 'nova-studija-otkriva-deka-umerenoto-vezhbanje-go-namaluva-rizikot-od-srcev-udar-za-35', 'Истражување објавено во European Heart Journal покажува дека дури и умерената физичка активност значително го намалува ризикот од кардиоваскуларни настани.', '<p>Најновото истражување објавено во престижното списание European Heart Journal донесува силни докази дека умерената физичка активност значително го намалува ризикот од кардиоваскуларни болести. Студијата, спроведена на повеќе од 100.000 учесници од 20 земји, покажува дека дури и 30 минути умерено вежбање дневно го намалува ризикот од срцев удар за 35%.</p><p></p><p>Истражувачите следеле група учесници во период од 12 години, мерејќи го нивното ниво на физичка активност преку преносливи уреди. Резултатите покажале дека најголема корист имаат лицата кои преминале од седентарен начин на живот кон умерено активен - нивниот ризик се намалил за дури 45%.</p><p>„Не е потребно интензивно вежбање за да се постигнат значајни здравствени придобивки,“ изјави водечкиот автор на студијата, д-р Мартин Хансон од Универзитетот во Оксфорд. „Дури и брзото одење, градинарството или возењето велосипед до работа може да направат огромна разлика.“</p><p>Студијата исто така ги идентификуваше петте најважни типови на физичка активност за здравјето на срцето: брзо одење, пливање, возење велосипед, аеробик и џогирање. Кардиолозите препорачуваат комбинација од аеробни вежби и вежби за сила најмалку 150 минути неделно.</p>', '/uploads/img104.jpg', '2', '1', 'false', '2026-06-03T16:16:14.293Z', '2026-06-03T16:25:27.644Z', 'DRAFT', 'Вежбање и срцев удар - нова студија', 'Умереното вежбање го намалува ризикот од срцев удар за 35%, покажува нова студија во European Heart Journal.', 'European Heart Journal', 'https://academic.oup.com/eurheartj'),
('14', 'Нов лек за Алцхајмерова болест покажува ветувачки резултати во фаза 3 клиничко испитување', 'nov-lek-za-alchajmerova-bolest-pokazhuva-vetuvachki-rezultati-vo-faza-3-klinichko-ispituvanje', 'Експерименталниот лек леканемаб го успорува когнитивниот пад кај пациенти со рана Алцхајмерова болест за 40%.', '<p>Новото клиничко испитување фаза 3, објавено во New England Journal of Medicine, донесе надеж за милиони пациенти ширум светот погодени од Алцхајмерова болест. Експерименталниот лек леканемаб, развиен од компаниите Eisai и Biogen, покажа дека го успорува когнитивниот пад кај пациенти со рана фаза на болеста за 40% во споредба со плацебо групата.</p><p></p><p>Испитувањето вклучи 1.795 пациенти со блага когнитивна попреченост или рана Алцхајмерова болест, потврдена со ПЕТ скен и присуство на амилоидни плаки во мозокот. Пациентите примаа интравенска инфузија на леканемаб на секои две недели, а резултатите беа мерени преку стандардизирани когнитивни тестови.</p><p>Леканемаб е моноклонално антитело кое го напаѓа и отстранува амилоид-бета протеинот од мозокот, кој се смета за една од главните причини за Алцхајмеровата болест. Покрај забавувањето на когнитивниот пад, третманот резултираше со значително намалување на амилоидните плаки, мерено преку ПЕТ скен.</p><p>Најчестите несакани ефекти вклучуваа реакции на местото на инфузија (24%) и церебрален едем (11%), кој во повеќето случаи беше асимптоматски и реверзибилен. Истражувачите препорачуваат редовен МР надзор при употреба на лекот.</p><p>За македонските пациенти со Алцхајмер, кои се проценува на околу 15.000, оваа вест носи надеж дека во иднина ќе биде достапен поефикасен третман за оваа разорна болест. Леканемаб веќе доби забрзано одобрение од FDA во 2024 година, а се очекува и одобрение од EMA до крајот на 2026 година.</p>', '/uploads/img105.jpg', '3', '1', 'true', '2026-06-03T16:16:14.298Z', '2026-06-03T16:25:27.641Z', 'DRAFT', 'Нов лек за Алцхајмер - леканемаб резултати', 'Фаза 3 испитување покажува дека леканемаб го успорува когнитивниот пад кај Алцхајмер за 40%.', 'New England Journal of Medicine', 'https://www.nejm.org/'),
('15', 'Транскранијална магнетна стимулација - нов пристап во третманот на мигрена', 'transkranijalna-magnetna-stimulacija-nov-pristap-vo-tretmanot-na-migrena', 'Нова неинвазивна терапија со магнетна стимулација покажува ефикасност кај пациенти со хронична мигрена.', '<p>Транскранијалната магнетна стимулација (TMS) се појавува како ветувачка неинвазивна опција за пациенти со хронична мигрена кои не реагираат на стандардната фармаколошка терапија. Најновото истражување објавено во The Lancet Neurology покажува дека редовната примена на TMS значително ја намалува фреквенцијата и интензитетот на мигренозните напади.</p><p></p><p>Студијата вклучи 248 пациенти со хронична мигрена (15 или повеќе дена со главоболка месечно) кои беа поделени во две групи. Едната група примаше активна TMS терапија, додека контролната група примаше sham (лажна) стимулација. По три месеци, групата со активна TMS пријави 45% намалување на бројот на денови со мигрена, во споредба со 18% во контролната група.</p><p>Механизмот на дејство на TMS се базира на модулација на кортикалната ексцитабилност и нормализирање на невронската активност во регионите на мозокот одговорни за перцепција на болка. TMS користи магнетни импулси кои генерираат електрични струи во специфични области на церебралниот кортекс.</p><p>Невролозите во Северна Македонија покажуваат зголемен интерес за оваа технологија, а Универзитетската клиника за неврологија во Скопје најави дека планира да воведе TMS третман за пациенти со хронична мигрена до крајот на оваа година.</p>', '/uploads/img106.jpg', '3', '1', 'false', '2026-06-03T16:16:14.303Z', '2026-06-03T16:25:27.639Z', 'DRAFT', 'Транскранијална магнетна стимулација за мигрена', 'Неинвазивната магнетна стимулација на мозокот нуди нов пристап за третман на хронична мигрена.', 'The Lancet Neurology', 'https://www.thelancet.com/journals/laneur'),
('16', 'Нов национален календар за имунизација на децата за 2026-2027 година', 'nov-nacionalen-kalendar-za-imunizacija-na-decata-za-2026-2027-godina', 'Министерството за здравство ја ажурираше програмата за задолжителна имунизација на децата со нови вакцини.', '<p>Министерството за здравство на Република Северна Македонија го објави ажурираниот календар за задолжителна имунизација на децата за периодот 2026-2027 година. Новиот календар вклучува неколку значајни промени, вклучително и воведување на нова комбинирана вакцина.</p><p></p><p>Најзначајната новина е вклучувањето на вакцината против респираторен синцицијален вирус (RSV) во задолжителната програма за имунизација, наменета за новороденчиња и доенчиња со зголемен ризик. RSV е една од водечките причини за хоспитализација кај деца под 2-годишна возраст, особено во зимските месеци.</p><p>Календарот исто така предвидува и измена на распоредот за дозирање на ХПВ вакцината, која сега се препорачува да се прими на 12-годишна возраст наместо на 14, што е во согласност со препораките на СЗО и Европскиот центар за контрола на болести.</p><p>Педијатрите во земјава ги поздравуваат промените, истакнувајќи дека редовната имунизација е една од најефикасните превентивни мерки за заштита на здравјето на децата. Процентот на вакцинирани деца во Северна Македонија во 2025 година изнесуваше 92%, што е благо зголемување во однос на претходната година.</p>', '/uploads/img107.jpg', '4', '1', 'true', '2026-06-03T16:16:14.308Z', '2026-06-03T16:25:27.636Z', 'DRAFT', 'Календар за вакцинација на деца 2026-2027', 'Ажуриран календар за задолжителна имунизација на деца во Северна Македонија за 2026-2027.', 'Министерство за здравство', 'https://zdravstvo.gov.mk/'),
('17', 'Зголемен број на алергии кај децата - педијатрите алармираат', 'zgolemen-broj-na-alergii-kaj-decata-pedijatrite-alarmiraat', 'Стапката на алергиски заболувања кај децата во пораст за 25% во последните пет години.', '<p>Македонското педијатриско здружение алармира дека бројот на деца со алергиски заболувања во Северна Македонија бележи континуиран пораст од 25% во последните пет години. Најчести алергии кај децата се алергискиот ринитис (45%), астма (30%), атопичен дерматитис (15%) и алергии на храна (10%).</p><p></p><p>Според педијатрите, главните фактори за зголемениот број на алергии вклучуваат генетска предиспозиција, промени во исхраната, зголемено загадување на воздухот и климатски промени. Особено загрижувачки е порастот на алергии на храна кај деца под 3-годишна возраст.</p><p>Педијатрите препорачуваат рано воведување на потенцијални алергени во исхраната на доенчињата, под надзор на педијатар, како стратегија за превенција на алергии. Новите насоки на Европската академија за алергологија сугерираат дека воведувањето на кикиритки и јајца помеѓу 4 и 6 месеци може да го намали ризикот од алергии.</p><p>Министерството за здравство најави формирање на национален регистер на алергиски заболувања кај децата, со цел подобро следење и управување со оваа растечка здравствена состојба.</p>', '/uploads/img108.jpg', '4', '1', 'false', '2026-06-03T16:16:14.311Z', '2026-06-03T16:25:27.632Z', 'DRAFT', 'Алергии кај деца - зголемен број случаи', 'Педијатрите известуваат за 25% пораст на алергиски заболувања кај децата во последните пет години.', 'Македонско педијатриско здружение', 'https://mpz.org.mk/'),
('18', 'Нови препораки за скрининг на колоректален карцином - возраста се намалува на 40 години', 'novi-preporaki-za-skrining-na-kolorektalen-karcinom-vozrasta-se-namaluva-na-40-godini', 'Американското здружение за рак препорачува скрининг за колоректален карцином да започнува на 40 наместо на 50 години.', '<p>Американското здружение за рак (American Cancer Society) ги ажурираше препораките за скрининг на колоректален карцином, намалувајќи ја препорачаната возраст за започнување на редовен скрининг од 50 на 40 години. Оваа промена доаѓа како резултат на алармантниот пораст на случаи на колоректален карцином кај лица под 50-годишна возраст.</p><p></p><p>Според најновите епидемиолошки податоци, инциденцата на колоректален карцином кај лицата на возраст од 40 до 49 години се зголемила за 35% во последната деценија. Истовремено, стапката кај постарите возрасни групи благо опаѓа, што укажува на промена во возрасната дистрибуција на болеста.</p><p>Онколозите препорачуваат неколку опции за скрининг: колоноскопија на секои 10 години, фекален имунохемиски тест (FIT) годишно, или КТ колонографија на секои 5 години. Изборот на метод зависи од индивидуалните фактори на ризик и преференции на пациентот.</p><p>Редовниот скрининг може да го намали ризикот од смрт од колоректален карцином за 60-70%, бидејќи овозможува откривање и отстранување на преканцерозни полипи пред да се развијат во инвазивен карцином. Онколозите во Македонија ги поддржуваат новите препораки и апелираат до граѓаните над 40 години да се консултираат со својот матичен лекар за скрининг.</p>', '/uploads/img102.jpg', '5', '1', 'false', '2026-06-03T16:16:14.315Z', '2026-06-03T16:25:27.629Z', 'DRAFT', 'Скрининг за колоректален карцином од 40 години', 'Нови препораки за скрининг на дебелото црево - возраста се намалува на 40 години поради зголемен број случаи кај помлади.', 'American Cancer Society', 'https://www.cancer.org/'),
('19', 'Глобална криза на ментално здравје кај младите - СЗО повикува на итна акција', 'globalna-kriza-na-mentalno-zdravje-kaj-mladite-szo-povikuva-na-itna-akcija', 'Светската здравствена организација известува дека 1 од 7 адолесценти ширум светот доживува ментално растројство.', '<p>Светската здравствена организација (СЗО) објави алармантен извештај за состојбата со менталното здравје кај младите луѓе ширум светот. Според извештајот, 1 од 7 адолесценти на возраст од 10 до 19 години доживува некакво ментално растројство, а само 30% од нив добиваат соодветна стручна помош.</p><p></p><p>Најчестите ментални растројства кај младите вклучуваат анксиозни растројства (34%), депресија (25%), нарушувања во однесувањето (18%) и нарушувања поврзани со траума (12%). Посебно загрижува порастот на самоубиства кај адолесцентите, кои претставуваат четврта водечка причина за смрт кај младите на возраст од 15 до 19 години.</p><p>Психијатрите во Северна Македонија известуваат за сличен тренд и во земјава. Бројот на млади пациенти кои бараат психијатриска помош се зголемил за 65% во последните три години. Најголем пораст е забележан кај анксиозните растројства и нарушувањата во исхраната.</p><p>СЗО препорачува итни мерки на национално ниво, вклучително зголемување на буџетот за ментално здравје, воведување на психолози во училиштата и намалување на стигмата поврзана со барање психијатриска помош.</p>', '/uploads/img111.jpg', '6', '1', 'true', '2026-06-03T16:16:14.320Z', '2026-06-03T16:25:27.626Z', 'DRAFT', 'Криза на ментално здравје кај младите - СЗО', 'СЗО алармира дека 1 од 7 млади луѓе има ментално растројство - повик за итна глобална акција.', 'World Health Organization', 'https://www.who.int/health-topics/mental-health'),
('20', 'Псилоцибинска терапија за депресија - нови клинички докази за ефикасноста', 'psilocibinska-terapija-za-depresija-novi-klinichki-dokazi-za-efikasnosta', 'Клиничко испитување покажува дека псилоцибинот, во комбинација со психотерапија, дава брзи и трајни резултати кај пациенти со резистентна депресија.', '<p>Новото клиничко испитување објавено во The BMJ донесува убедливи докази за ефикасноста на псилоцибинската терапија кај пациенти со резистентна депресија. Студијата, спроведена на Универзитетот Џонс Хопкинс, покажа дека единечна доза на псилоцибин, администрирана во контролирана клиничка средина во комбинација со психотерапија, доведува до значително намалување на симптомите на депресија кај 71% од пациентите.</p><p></p><p>Испитувањето вклучи 104 пациенти со дијагностицирана депресија кои не реагирале на најмалку два претходни антидепресивни третмани. Пациентите примија единечна доза на псилоцибин (25 мг) во надгледувана средина, проследена со 12 сесии на интегративна психотерапија во текот на 12 недели.</p><p>Резултатите покажаа дека 71% од пациентите доживеале значително намалување на симптомите на депресија (мерено со скалата MADRS) по три недели, а 65% останале во ремисија по 12 недели. За споредба, во плацебо групата, само 18% покажале значително подобрување.</p><p>Психијатрите потенцираат дека оваа терапија треба да се спроведува исклучиво во контролирана клиничка средина под надзор на обучени професионалци. Моментално се во тек неколку фаза 3 испитувања, а одобрување од FDA се очекува во текот на 2027 година.</p>', '/uploads/img112.jpg', '6', '1', 'false', '2026-06-03T16:16:14.328Z', '2026-06-03T16:25:27.624Z', 'DRAFT', 'Псилоцибинска терапија за депресија - резултати', 'Ново клиничко испитување покажува дека псилоцибинот е ефикасен третман за резистентна депресија.', 'The BMJ', 'https://www.bmj.com/'),
('21', 'Нови техники во имплантологијата - дигитално планирање и 3Д печатење', 'novi-tehniki-vo-implantologijata-digitalno-planiranje-i-3d-pechatenje', 'Дигиталните технологии го револуционизираат планирањето и изведбата на дентални импланти.', '<p>Стоматологијата бележи револуционерен напредок благодарение на дигиталните технологии кои овозможуваат прецизно планирање и изработка на дентални импланти. Комбинацијата на КБКТ (конусна-зрак компјутеризирана томографија), дигитално скенирање и 3Д печатење овозможува создавање на импланти кои совршено одговараат на анатомијата на пациентот.</p><p></p><p>Според најновите истражувања објавени во Journal of Dental Research, дигитално планираните импланти имаат стапка на успех од 97.5%, во споредба со 92.3% кај традиционалните методи. Дополнително, времето на процедурата е намалено за 40%, а постоперативниот опоравак е побрз.</p><p>Стоматолошките клиники во Северна Македонија постепено воведуваат дигитални технологии. Неколку приватни клиники веќе нудат ЦАД/ЦАМ изработка на импланти и 3Д печатени хируршки водичи, а Универзитетската клиника за стоматологија во Скопје најави отворање на центар за дигитална стоматологија.</p><p>Цената на дигиталните импланти е повисока од традиционалните, но долгорочните придобивки, вклучително помала стапка на компликации и подолг век на траење, ја прават оваа опција исплатлива за пациентите.</p>', '/uploads/img113.jpg', '7', '1', 'true', '2026-06-03T16:16:14.333Z', '2026-06-03T16:25:27.621Z', 'DRAFT', 'Дигитална имплантологија - 3Д печатење импланти', 'Нови дигитални техники во денталната имплантологија овозможуваат попрецизно и побрзо поставување импланти.', 'Journal of Dental Research', 'https://journals.sagepub.com/home/jdr'),
('22', 'Врската помеѓу оралното здравје и кардиоваскуларните болести', 'vrskata-pomegju-oralnoto-zdravje-i-kardiovaskularnite-bolesti', 'Стоматолозите и кардиолозите ги обединуваат силите за да ја истакнат важноста на оралната хигиена за здравјето на срцето.', '<p>Сè повеќе научни докази укажуваат на директна врска помеѓу оралното здравје и ризикот од кардиоваскуларни болести. Пародонталната болест (воспаление на непцата) го зголемува ризикот од срцев удар за 25% и од мозочен удар за 30%, според мета-анализа објавена во Journal of Periodontology.</p><p></p><p>Механизмот на поврзаност се базира на хроничното воспаление предизвикано од бактериите во усната празнина. Овие бактерии можат да влезат во крвотокот преку воспалените непца и да предизвикаат системско воспаление, забрзувајќи го процесот на атеросклероза.</p><p>Стоматолозите препорачуваат редовни стоматолошки прегледи на секои шест месеци, правилно четкање на забите два пати дневно, користење забен конец и избегнување на пушење како основни мерки за одржување на оралното здравје. Посебен акцент се става на пациентите со веќе дијагностицирани кардиоваскуларни болести.</p><p>Во Северна Македонија, стоматолошката комора започна едукативна кампања за подигање на свеста за врската помеѓу оралното и општото здравје, насочена кон пациенти над 40-годишна возраст.</p>', '/uploads/img114.jpg', '7', '1', 'false', '2026-06-03T16:16:14.339Z', '2026-06-03T16:25:27.618Z', 'DRAFT', 'Орално здравје и срцеви болести - врска', 'Научни докази покажуваат дека болестите на непцата го зголемуваат ризикот од срцев удар и мозочен удар.', 'Journal of Periodontology', 'https://www.aap.org/jop'),
('23', 'Нова ера во третманот на дијабетес - GLP-1 агонистите покажуваат повеќекратни придобивки', 'nova-era-vo-tretmanot-na-dijabetes-glp-1-agonistite-pokazhuvaat-povekjekratni-pridobivki', 'Најновите лекови од класата GLP-1 агонисти не само што го контролираат шеќерот, туку и помагаат при намалување на телесната тежина.', '<p>Класата на лекови познати како GLP-1 агонисти претставува една од најзначајните иновации во фармацијата во последните години. Првично развиени за третман на дијабетес тип 2, овие лекови покажаа исклучителна ефикасност и во намалувањето на телесната тежина, што доведе до нивно одобрување и за третман на дебелина.</p><p></p><p>Најпознатиот претставник на оваа класа, семаглутид (продаван под трговските имиња Ozempic и Wegovy), покажа дека просечно намалување на телесната тежина од 15-20% кај пациенти со дебелина. Дополнително, студиите покажаа дека истиот лек го намалува ризикот од кардиоваскуларни настани за 26%, независно од ефектот врз телесната тежина.</p><p>Фармацевтите предупредуваат дека овие лекови не се „чудотворни таблети“ и дека нивната употреба треба да биде под строг медицински надзор. Најчестите несакани ефекти вклучуваат мачнина, повраќање и дијареја, а постои и ризик од панкреатит кај ретки случаи.</p><p>Во Северна Македонија, GLP-1 агонистите се достапни на рецепт и делумно се покриени од Фондот за здравствено осигурување за пациенти со дијабетес. Фармацевтската комора работи на едукација на фармацевтите за правилно советување на пациентите за овие лекови.</p>', '/uploads/img115.jpg', '8', '1', 'true', '2026-06-03T16:16:14.343Z', '2026-06-03T16:25:27.614Z', 'DRAFT', 'GLP-1 агонисти - нова ера во третман на дијабетес', 'Лековите GLP-1 покажуваат исклучителни резултати во контрола на шеќер и намалување на телесна тежина.', 'European Medicines Agency', 'https://www.ema.europa.eu/'),
('24', 'Антибиотска резистенција - глобална закана која бара итно дејствување', 'antibiotska-rezistencija-globalna-zakana-koja-bara-itno-dejstvuvanje', 'СЗО предупредува дека антибиотската резистенција би можела да предизвика 10 милиони смртни случаи годишно до 2050 година.', '<p>Антибиотската резистенција претставува една од најголемите закани за глобалното јавно здравје во 21-от век. Светската здравствена организација проценува дека доколку не се преземат итни мерки, до 2050 година антибиотски-резистентните инфекции би можеле да предизвикаат 10 милиони смртни случаи годишно, надминувајќи ја смртноста од рак.</p><p></p><p>Главната причина за развојот на резистенција е прекумерната и несоодветна употреба на антибиотици. Според фармацевтските податоци, во Северна Македонија, 45% од антибиотиците се препишуваат за вирусни инфекции каде тие се неефикасни. Дополнително, значаен проблем е и самолекувањето со антибиотици без рецепт.</p><p>Фармацевтите имаат клучна улога во борбата против антибиотската резистенција. Тие се должни да советуваат пациенти за правилна употреба на антибиотици, да инсистираат на завршување на целосниот третман и да одбиваат издавање без рецепт.</p><p>Министерството за здравство, во соработка со Фармацевтската комора, започна национална кампања за рационална употреба на антибиотици, насочена кон лекарите, фармацевтите и пациентите.</p>', '/uploads/img116.jpg', '8', '1', 'false', '2026-06-03T16:16:14.346Z', '2026-06-03T16:25:27.611Z', 'DRAFT', 'Антибиотска резистенција - глобална закана 2026', 'Антибиотската резистенција се заканува да го врати светот во ера без ефикасни антибиотици - СЗО повикува на акција.', 'World Health Organization', 'https://www.who.int/health-topics/antimicrobial-resistance'),
('25', 'Медитеранската исхрана прогласена за најдобра диета за 2026 година по шести пат', 'mediteranskata-ishrana-proglasena-za-najdobra-dieta-za-2026-godina-po-shesti-pat', 'Американското здружение за срце повторно ја рангира медитеранската исхрана како најздрава, поткрепена со нови научни докази.', '<p>Медитеранската исхрана по шести последователен пат е прогласена за најдобра диета за 2026 година од страна на Американското здружение за срце (AHA). Оваа традиционален начин на исхрана, карактеристичен за земјите од Медитеранот, продолжува да биде златен стандард во препораките за здрава исхрана.</p><p></p><p>Нутриционистите потенцираат дека медитеранската исхрана е богата со маслиново масло, риба, овошје, зеленчук, цели зрна и ореви, а сиромашна со црвено месо и преработена храна. Најновите истражувања покажуваат дека строгото придржување кон медитеранската исхрана го намалува ризикот од кардиоваскуларни болести за 32%, дијабетес тип 2 за 28% и одредени видови на рак за 18%.</p><p>За македонските граѓани, медитеранската исхрана е природен избор, бидејќи многу од препорачаните намирници се локално достапни и традиционално дел од македонската кујна. Маслиновото масло, свежиот зеленчук, рибата од Охридското Езеро и домашното овошје се лесно достапни.</p><p>Нутриционистите препорачуваат постепено воведување на медитеранските принципи во секојдневната исхрана: замена на рафинираните масла со маслиново, зголемување на внесот на риба на најмалку 2 пати неделно и вклучување на свеж зеленчук во секој оброк.</p>', '/uploads/img117.jpg', '9', '1', 'true', '2026-06-03T16:16:14.350Z', '2026-06-03T16:25:27.608Z', 'DRAFT', 'Медитеранска исхрана - најдобра диета 2026', 'Медитеранската исхрана по шести последователен пат е прогласена за најдобра диета од страна на кардиолозите.', 'American Heart Association', 'https://www.heart.org/'),
('26', 'Витамин Д - нова студија открива оптимални нивоа за превенција на хронични болести', 'vitamin-d-nova-studija-otkriva-optimalni-nivoa-za-prevencija-na-hronichni-bolesti', 'Научниците утврдија дека оптималните нивоа на витамин Д се повисоки од претходно препорачаните.', '<p>Најновото истражување објавено во The American Journal of Clinical Nutrition ги ревидира препораките за оптимални нивоа на витамин Д во крвта. Студијата, спроведена на 15.000 учесници од 12 земји, утврди дека нивоата помеѓу 50-80 ng/mL се поврзани со најнизок ризик од хронични болести.</p><p></p><p>Витаминот Д игра клучна улога во повеќе физиолошки процеси, вклучително апсорпција на калциум, имунолошка функција и регулација на воспаление. Ниските нивоа на витамин Д се поврзани со зголемен ризик од остеопороза, кардиоваскуларни болести, автоимуни болести и одредени видови на рак.</p><p>Во Северна Македонија, 65% од населението има недоволно ниво на витамин Д, особено во зимските месеци кога изложеноста на сончева светлина е намалена. Нутриционистите препорачуваат суплементација на витамин Д во текот на есента и зимата, во доза од 1000-2000 IU дневно.</p><p>Најдобрите природни извори на витамин Д вклучуваат мрсна риба (лосос, скуша, сардини), жолчка од јајце, говедски црн дроб и збогатени млечни производи. Изложеноста на сонце од 15-20 минути дневно, во зависност од сезоната, исто така значително придонесува за синтеза на витамин Д.</p>', '/uploads/img118.jpg', '9', '1', 'false', '2026-06-03T16:16:14.357Z', '2026-06-03T16:25:27.605Z', 'DRAFT', 'Витамин Д - оптимални нивоа за здравје 2026', 'Нова студија ги ревидира препораките за витамин Д - повисоки нивоа за превенција на хронични болести.', 'The American Journal of Clinical Nutrition', 'https://academic.oup.com/ajcn'),
('27', 'Вештачка интелигенција во радиологијата - нови алгоритми ги надминуваат радиолозите во откривање на тумори', 'veshtachka-inteligencija-vo-radiologijata-novi-algoritmi-gi-nadminuvaat-radiolozite-vo-otkrivanje-na-tumori', 'Алгоритмите за длабока учење постигнаа 98% точност во откривањето на малигни лезии на КТ и МР снимки.', '<p>Најновите алгоритми за вештачка интелигенција во радиологијата покажуваат извонредни резултати, постигнувајќи 98% точност во откривањето на малигни лезии на КТ и МР снимки, според студија објавена во Nature Medicine. Оваа точност е за 5% повисока од просечната точност на човечките радиолози во истата студија.</p><p></p><p>Системот, развиен од истражувачи на Универзитетот Стенфорд, користи конволутивни невронски мрежи обучени на повеќе од 2 милиони медицински снимки. Алгоритмот е способен да идентификува суптилни промени во ткивото кои можат да укажат на присуство на малигнитет, вклучително и во многу рана фаза.</p><p>Значајно е што системот покажува особено висока точност во откривањето на рак на бели дробови (99.2%), рак на дојка (97.8%) и тумори на мозокот (96.5%). Дополнително, алгоритмот генерира и топлински мапи кои ги покажуваат регионите на снимата што го поттикнале заклучокот.</p><p>Медицинските технологи во Северна Македонија следат развој, а неколку болници започнаа пилот-проекти за имплементација на ВИ асистирана дијагностика. Засега, ВИ системите се користат како алатка за поддршка на одлуки, а не како замена за радиолозите.</p>', '/uploads/img119.jpg', '10', '1', 'true', '2026-06-03T16:16:14.363Z', '2026-06-03T16:25:27.601Z', 'DRAFT', 'ВИ во радиологија - надминува радиолози во точност', 'Нови алгоритми за вештачка интелигенција постигнаа 98% точност во откривањето на тумори на медицински снимки.', 'Nature Medicine', 'https://www.nature.com/nm/'),
('28', 'Носливи уреди за следење на здравјето - од фитнес тракери до медицински дијагностички алатки', 'noslivi-uredi-za-sledenje-na-zdravjeto-od-fitnes-trakeri-do-medicinski-dijagnostichki-alatki', 'Паметните часовници и други носливи уреди стануваат се поточни во следењето на здравствени параметри.', '<p>Носливите уреди за следење на здравјето еволуираа од едноставни фитнес тракери до софистицирани дијагностички алатки способни да следат широк спектар на здравствени параметри. Најновите модели на паметни часовници можат да регистрираат ЕКГ, да го мерат кислородот во крвта, да следат квалитет на сон и да откриваат аритмии.</p><p></p><p>Според анализа на MIT Technology Review, 34% од возрасните во САД и Европа користат нослив уред за следење на здравјето, а се очекува овој број да надмине 50% до 2030 година. Најзначајниот напредок е забележан во континуираното мерење на глукоза, кое повеќе не бара пробивање на кожата.</p><p>Во Северна Македонија, употребата на носливи уреди расте, но сè уште е под европскиот просек. Македонските лекари се воздржани во користењето на податоците од овие уреди за клинички одлуки, поради недостаток на стандардизација и валидација.</p><p>Експертите предвидуваат дека носливите уреди ќе играат клучна улога во иднината на превентивната медицина, овозможувајќи рано откривање на здравствени проблеми пред да се појават симптоми.</p>', '/uploads/img120.jpg', '10', '1', 'false', '2026-06-03T16:16:14.366Z', '2026-06-03T16:25:27.596Z', 'DRAFT', 'Носливи уреди за здравје - преглед 2026', 'Од ЕКГ до мерење на шеќер - како паметните часовници стануваат медицински алатки.', 'MIT Technology Review', 'https://www.technologyreview.com/'),
('29', 'Откриен нов антивирусен лек кој покажува ефикасност против сите четири соеви на денга вирус', 'otkrien-nov-antivirusen-lek-koj-pokazhuva-efikasnost-protiv-site-chetiri-soevi-na-denga-virus', 'Клиничка студија објавена во The Lancet Infectious Diseases покажува дека новиот лек го намалува ризикот од тешка форма на денга за 70%.', '<p>Научниците објавија ветувачки резултати од клиничкото испитување на нов антивирусен лек насочен против денга треската, болест која погодува околу 400 милиони луѓе годишно. Лекот, привремено наречен JD-2026, покажа 70% ефикасност во намалувањето на ризикот од тешка форма на болеста, истовремено делувајќи против сите четири познати соеви на вирусот.</p><p></p><p>Студијата, спроведена во 15 медицински центри во Бразил, Индија и Тајланд, вклучи 1.200 пациенти со потврдена денга инфекција. Пациентите кои го примиле JD-2026 во првите 48 часа од појавата на симптомите покажале значително побрзо повлекување на симптомите (просечно 2.3 дена наспроти 5.7 дена) и 70% помал ризик од развој на тешка форма на болеста.</p><p>Денга треската претставува зголемена закана и за Европа, поради ширењето на комарецот Aedes aegypti како резултат на климатските промени. Во 2025 година, првите автохтони случаи на денга беа регистрирани и во Јужна Европа, вклучително и во соседна Грција.</p>', '/uploads/img126.jpg', '11', '1', 'false', '2026-06-03T16:16:14.371Z', '2026-06-03T16:25:27.593Z', 'DRAFT', 'Нов антивирусен лек против денга - клиничка студија', 'Лекот JD-2026 покажува 70% ефикасност против сите четири соеви на денга вирус во фаза 2 испитување.', 'The Lancet Infectious Diseases', 'https://www.thelancet.com/journals/laninf'),
('30', 'Професионални заболувања кај градежните работници - превенција и заштита', 'profesionalni-zaboluvanja-kaj-gradezhnite-rabotnici-prevencija-i-zashtita', 'Градежништвото е еден од секторите со највисок ризик за професионални заболувања и повреди при работа.', '<p>Градежништвото останува еден од најризичните сектори за професионални заболувања и повреди, според најновиот извештај на Меѓународната организација на трудот (ILO). Работниците во градежништвото се изложени на широк спектар на здравствени ризици, вклучително физички повреди, респираторни заболувања и оштетување на слухот.</p><p></p><p>Најчестите професионални заболувања кај градежните работници вклучуваат респираторни заболувања предизвикани од вдишување на прашина и хемиски материи (25%), оштетување на слухот поради бучава (20%), мускулно-скелетни нарушувања (30%) и дерматитис (10%). Според податоците на Институтот за јавно здравје, во Северна Македонија, просечно 350 градежни работници годишно пријавуваат професионална болест.</p><p>Превенцијата е клучна. Работодавачите се должни да обезбедат соодветна лична заштитна опрема, вклучително респиратори, заштитни каски, ракавици и обувки. Дополнително, задолжителни се редовни лекарски прегледи на секои 12 месеци, како и обуки за безбедност при работа.</p><p>Медицината на труд препорачува воведување на програми за ергономија на работното место, ротација на работните задачи за намалување на монотоните движења и редовни паузи за одмор. Особено значајно е и подигањето на свеста за важноста на пријавување на здравствени проблеми во рана фаза.</p>', '/uploads/img122.jpg', '12', '1', 'true', '2026-06-03T16:19:22.891Z', '2026-06-03T16:25:27.583Z', 'DRAFT', 'Професионални заболувања кај градежни работници', 'Превенција и заштита на градежните работници од професионални заболувања - прирачник за безбедност при работа.', 'Меѓународна организација на трудот', 'https://www.ilo.org/'),
('31', 'Синдром на изгорување на работното место - Burnout синдром кај здравствените работници', 'sindrom-na-izgoruvanje-na-rabotnoto-mesto-burnout-sindrom-kaj-zdravstvenite-rabotnici', 'Истражување покажува дека 45% од здравствените работници во Северна Македонија покажуваат симптоми на професионален burnout.', '<p>Синдромот на професионално изгорување (burnout) кај здравствените работници достигна алармантни размери. Најновото истражување спроведено од Институтот за јавно здравје покажува дека 45% од здравствените работници во Северна Македонија покажуваат симптоми на burnout, а 18% се во тешка фаза која бара итна интервенција.</p><p></p><p>Синдромот се карактеризира со три главни симптоми: емоционална исцрпеност, деперсонализација (циничен однос кон пациентите) и намалено чувство на лично постигнување. Најзагрозени се вработените во итната медицина, интензивната нега и ковид-одделите.</p><p>Главните причини за burnout вклучуваат прекумерно работно оптоварување, недостаток на контрола врз работните задачи, несоодветна награда и признание, недостаток на поддршка од колеги и менаџмент, и конфликтни вредности. Просечната работна недела на лекарите во државните болници изнесува 56 часа.</p><p>Медицината на труд препорачува воведување на програми за превенција на burnout на институционално ниво, вклучително психолошка поддршка за вработените, обуки за управување со стрес, флексибилно работно време и редовни супервизии. Министерството за здравство најави формирање на советувалишта за ментално здравје на здравствените работници.</p>', '/uploads/img123.jpg', '12', '1', 'false', '2026-06-03T16:19:22.901Z', '2026-06-03T16:25:27.579Z', 'DRAFT', 'Burnout синдром кај здравствени работници', '45% од здравствените работници во Македонија покажуваат симптоми на професионално изгорување - итна потреба од превентивни мерки.', 'СЗО - Ментално здравје на работното место', 'https://www.who.int/health-topics/occupational-health'),
('32', 'Изложеност на хемиски супстанции на работното место - нови регулативи за 2026', 'izlozhenost-na-hemiski-supstancii-na-rabotnoto-mesto-novi-regulativi-za-2026', 'Европската унија воведува построги граници за изложеност на опасни хемиски супстанции на работното место.', '<p>Европската комисија донесе нови регулативи за заштита на работниците од изложеност на опасни хемиски супстанции, кои стапуваат во сила од 1 јануари 2026 година. Новите правила воведуваат построги гранични вредности за професионална изложеност за 15 хемиски агенси, вклучително кристален силициум диоксид, формалдехид и олово.</p><p></p><p>Кристалниот силициум диоксид, кој се ослободува при сечење камен, брусење бетон и обработка на керамика, доби нов граничен лимит од 0.05 mg/m³ (намален од 0.1 mg/m³). Оваа промена директно влијае на градежниот сектор и индустриите за преработка на камен. Формалдехидот, присутен во болниците и лабораториите, доби лимит од 0.3 ppm.</p><p>Како земја кандидат за членство во ЕУ, Северна Македонија има обврска да ги усогласи своите регулативи со европските стандарди. Министерството за труд и социјална политика најави формирање на работна група за имплементација на новите стандарди во националното законодавство.</p><p>Работодавачите се должни да извршат процена на ризикот од хемиски супстанции на работното место, да обезбедат соодветна вентилација и лична заштитна опрема, и да спроведуваат редовно мерење на концентрацијата на штетни материи во воздухот. Надлежниот инспекторат за труд најави засилени контроли.</p>', '/uploads/img124.jpg', '12', '1', 'false', '2026-06-03T16:19:22.905Z', '2026-06-03T16:25:27.576Z', 'DRAFT', 'Регулативи за хемиски супстанции на работно место 2026', 'ЕУ воведува построги граници за изложеност на опасни хемикалии на работното место - импликации за Македонија.', 'Европска агенција за безбедност и здравје при работа', 'https://osha.europa.eu/'),
('33', 'Ергономија на работното место - превенција на мускулно-скелетни нарушувања', 'ergonomija-na-rabotnoto-mesto-prevencija-na-muskulno-skeletni-narushuvanja', 'Мускулно-скелетните нарушувања се водечка причина за отсутвo од работа и инвалидитет во Европа.', '<p>Мускулно-скелетните нарушувања (МСН) претставуваат водечка причина за отсутвo од работа и инвалидитет во Европа, погодувајќи 30% од работниците. Според Европската агенција за безбедност и здравје при работа, трошоците поврзани со МСН изнесуваат 2% од БДП на ЕУ годишно. Во Северна Македонија, МСН сочинуваат 35% од сите пријавени професионални заболувања.</p><p></p><p>Најчестите мускулно-скелетни нарушувања вклучуваат болки во долниот дел на грбот (40%), болки во вратот и рамената (30%) и синдром на карпален тунел (15%). Главните фактори на ризик вклучуваат продолжено седење, неправилно држење на телото, повторливи движења, вибрации и рачна работа со тешки товари.</p><p>Специјалистите по медицина на труд препорачуваат неколку клучни ергономски мерки: прилагодување на висината на столот и мониторот, користење на ергономски тастатури и глувчиња, редовни паузи за истегнување на секој 30 минути, и употреба на соодветна опрема за подигање тешки товари.</p><p>Работодавачите се законски обврзани да обезбедат процена на ергономските ризици на работното место и да преземат превентивни мерки. Овие мерки не само што го штитат здравјето на работниците, туку и ја зголемуваат продуктивноста и го намалуваат отсутвoто од работа.</p>', '/uploads/img125.jpg', '12', '1', 'true', '2026-06-03T16:19:22.908Z', '2026-06-03T16:25:27.561Z', 'DRAFT', 'Ергономија на работното место - превенција', 'Практични совети за ергономско уредување на работното место и превенција на мускулно-скелетни нарушувања.', 'Европска агенција за безбедност и здравје при работа', 'https://osha.europa.eu/');

